3	pub fn write_interface(item: &metadata::reader::TypeDef) -> Result<TokenStream, Error> {
4	    let namespace = item.namespace();
5	    let name = write_ident(item.name());
6	
7	    let (generics, generics_tokens) = write_generic_params(item);
8	
9	    let methods: Vec<TokenStream> = item
10	        .methods()
11	        .map(|method| write_method(namespace, &method, &generics))
12	        .collect::<Result<Vec<_>, _>>()?;
13	
14	    let requires: Vec<_> = item.interface_impls().collect();
15	
16	    let requires_tokens = if requires.is_empty() {
17	        quote! {}
18	    } else {
19	        let ifaces = requires
20	            .iter()
21	            .map(|imp| write_type(namespace, &imp.interface(&generics)));
22	        quote! { : #(#ifaces)+* }
23	    };
24	
25	    let guid_token = match interface_guid_output(item, &generics)? {
26	        GuidOutput::None => quote! { #[no_guid] },
27	        GuidOutput::Omit => quote! {},
28	        GuidOutput::Explicit(d1, d2, d3, d4) => {
29	            let lit = syn::LitInt::new(&format_guid_u128(d1, d2, d3, d4), Span::call_site());
30	            quote! { #[guid(#lit)] }
31	        }
32	    };
33	    let custom_attrs = write_custom_attributes_except(
34	        item.attributes(),
35	        namespace,
36	        item.index(),
37	        &["GuidAttribute"],
38	    )?;
39	
40	    Ok(quote! {
41	        #guid_token
42	        #(#custom_attrs)*
43	        interface #name #generics_tokens #requires_tokens {
44	            #(#methods)*
45	        }
46	    })
47	}
48	
49	fn write_method(
50	    namespace: &str,
51	    item: &metadata::reader::MethodDef,
52	    generics: &[metadata::Type],
53	) -> Result<TokenStream, Error> {
54	    let name = write_ident(item.name());
55	    let signature = item.signature(generics);
56	
57	    let return_type = write_return_type(namespace, item, &signature)?;
58	    let params = std::iter::once(Ok(quote! { &self }))
59	        .chain(
60	            write_params(namespace, item, signature.types)?
61	                .into_iter()
62	                .map(Ok),
63	        )
64	        .collect::<Result<Vec<_>, Error>>()?;
65	
66	    let method_attrs = write_custom_attributes(item.attributes(), namespace, item.index())?;
67	
68	    // Emit the built-in `#[special]` pseudo-attribute when SpecialName is set,
69	    // preserving properties and events on round-trip.
70	    let special_attr = if item
71	        .flags()
72	        .contains(metadata::MethodAttributes::SpecialName)
73	    {
74	        quote! { #[special] }
75	    } else {
76	        quote! {}
77	    };
78	
79	    Ok(quote! {
80	        #special_attr
81	        #(#method_attrs)*
82	        fn #name(#(#params),*) #return_type;
83	    })
84	}
