4	pub struct Index<'a> {
5	    pub namespaces: BTreeMap<String, Namespace<'a>>,
6	}
7	
8	#[derive(Default)]
9	pub struct Namespace<'a> {
10	    pub types: BTreeMap<String, Vec<(&'a File, &'a Item)>>,
11	    pub functions: BTreeMap<String, Vec<(&'a File, &'a Item)>>,
12	    pub constants: BTreeMap<String, Vec<(&'a File, &'a Item)>>,
13	}
14	
15	impl<'a> Index<'a> {
16	    pub fn new() -> Self {
17	        Self::default()
18	    }
19	
20	    pub fn insert(&mut self, file: &'a File, namespace: &str, item: &'a Item) {
21	        if let Item::Module(module) = item {
22	            let name = module.to_string();
23	            for item in &module.items {
24	                let namespace = if namespace.is_empty() {
25	                    name.clone()
26	                } else {
27	                    format!("{namespace}.{}", &name)
28	                };
29	                self.insert(file, &namespace, item);
30	            }
31	        } else {
32	            let namespace = self.namespaces.entry(namespace.to_string()).or_default();
33	
34	            match item {
35	                Item::Fn(..) => {
36	                    namespace
37	                        .functions
38	                        .entry(item.to_string())
39	                        .or_default()
40	                        .push((file, item));
41	                }
42	                Item::Const(..) => {
43	                    namespace
44	                        .constants
45	                        .entry(item.to_string())
46	                        .or_default()
47	                        .push((file, item));
48	                }
49	                _ => {
50	                    namespace
51	                        .types
52	                        .entry(item.to_string())
53	                        .or_default()
54	                        .push((file, item));
55	                }
56	            }
57	        }
58	    }
59	
60	    pub fn contains(&self, namespace: &str, name: &str) -> bool {
61	        self.namespaces
62	            .get(namespace)
63	            .and_then(|namespace| namespace.types.get(name))
64	            .is_some_and(|v| !v.is_empty())
65	    }
66	
67	    pub fn is_value_type(&self, namespace: &str, name: &str) -> bool {
68	        self.namespaces
69	            .get(namespace)
70	            .and_then(|namespace| namespace.types.get(name))
71	            .and_then(|v| v.first())
72	            .map(|(_, item)| matches!(item, Item::Struct(_) | Item::Enum(_) | Item::Union(_)))
73	            .unwrap_or(false)
74	    }
75	
76	    pub fn get<'b>(&'b self, namespace: &str, name: &str) -> impl Iterator<Item = &'b Item> {
77	        self.namespaces
78	            .get(namespace)
79	            .and_then(|namespace| namespace.types.get(name))
80	            .into_iter()
81	            .flatten()
82	            .map(|(_, item)| *item)
83	    }
84	
85	    /// Returns `Some(true)` if the named type is a WinRT type in the local index,
86	    /// `Some(false)` if it is non-WinRT, or `None` if the type is not in the local index.
87	    pub fn is_winrt(&self, namespace: &str, name: &str) -> Option<bool> {
88	        self.namespaces
89	            .get(namespace)
90	            .and_then(|ns| ns.types.get(name))
91	            .and_then(|v| v.first())
92	            .map(|(_, item)| match item {
93	                Item::Struct(s) => s.winrt,
94	                Item::Enum(e) => e.winrt,
95	                Item::Interface(i) => i.winrt,
96	                Item::Attribute(a) => a.winrt,
97	                // Delegates and classes are always WinRT.
98	                Item::Delegate(_) | Item::Class(_) => true,
99	                // Unions and callbacks are always non-WinRT.
100	                Item::Union(_) | Item::Callback(_) => false,
101	                Item::Fn(_) | Item::Const(_) | Item::Module(_) => false,
102	            })
103	    }
