use super::*;

syn::custom_keyword!(interface);
syn::custom_keyword!(event);

#[derive(Debug)]
pub struct Interface {
    pub attrs: Vec<syn::Attribute>,
    pub token: interface,
    pub name: syn::Ident,
    pub generics: syn::Generics,
    pub requires: Vec<syn::Path>,
    pub members: Vec<InterfaceMember>,
    pub winrt: bool,
}

/// A member declared inside an interface body.
#[derive(Debug)]
pub enum InterfaceMember {
    Method(Method),
    Property(Property),
    Event(Event),
}

/// Represents a property shorthand declaration inside an interface body.
///
/// Parsed from the syntax `[#[get] | #[set]] Name: Type;`. Without any attribute, both a
/// getter and a setter are generated; with `#[get]`, only a getter is generated; with
/// `#[set]`, only a setter is generated.
#[derive(Debug)]
pub struct Property {
    pub attrs: Vec<syn::Attribute>,
    pub name: syn::Ident,
    pub ty: syn::Type,
}

/// Represents an event shorthand declaration inside a WinRT interface body.
///
/// Parsed from the syntax `event Name: HandlerType;`. Generates `add_Name` and
/// `remove_Name` method pairs with the `SpecialName` flag.
#[derive(Debug)]
pub struct Event {
    pub name: syn::Ident,
    pub handler_ty: syn::Type,
}

impl Property {
    /// Determines which accessors this property generates based on its attributes.
    ///
    /// Returns `(emit_getter, emit_setter)`. Validation of the attributes happens at parse
    /// time so by this point the attributes are known to be some combination of `#[get]`
    /// and `#[set]` only.
    fn accessors(&self) -> (bool, bool) {
        let has_get = self.attrs.iter().any(|a| a.path().is_ident("get"));
        let has_set = self.attrs.iter().any(|a| a.path().is_ident("set"));

        match (has_get, has_set) {
            (true, false) => (true, false),
            (false, true) => (false, true),
            // No attribute means a read-write property.
            _ => (true, true),
        }
    }
}

impl syn::parse::Parse for InterfaceMember {
    fn parse(input: syn::parse::ParseStream) -> syn::Result<Self> {
        let attrs = input.call(syn::Attribute::parse_outer)?;

        if input.peek(event) {
