    /// Encodes a regular `fn` interface method, including its `&self` receiver check,
    /// parameter/return type validation, custom attributes, and the `#[special]` flag.
    fn encode_interface_method(
        &mut self,
        item: &Interface,
        method: &Method,
        base_flags: metadata::MethodAttributes,
        already_has_guid: bool,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
    ) -> Result<(), Error> {
        let mut params = vec![];

        if method.sig.inputs.is_empty() {
            return self.err(&method.sig.ident, "`&self` parameter not found");
        }

        for (sequence, arg) in method.sig.inputs.iter().enumerate() {
            match arg {
                syn::FnArg::Receiver(receiver) => {
                    if *receiver != syn::parse_quote! { &self } {
                        return self.err(receiver, "`&self` parameter not found");
                    }
                }
                syn::FnArg::Typed(pt) => {
                    if sequence == 0 {
                        return self.err(arg, "`&self` parameter not found");
                    }
                    let p = self.param(pt)?;
                    if item.winrt {
                        self.validate_type_is_winrt(&pt.ty, &p.ty)?;
                    }
                    params.push(p);
                }
            }
        }

        let types: Vec<metadata::Type> = params.iter().map(|param| param.ty.clone()).collect();
        let return_type = self.encode_return_type(&method.sig.output)?;

        if item.winrt {
            if let syn::ReturnType::Type(_, return_syn_ty) = &method.sig.output {
                self.validate_type_is_winrt(return_syn_ty.as_ref(), &return_type)?;
            }
        }

        if !already_has_guid {
            method_signatures.push((
                method.sig.ident.to_string(),
                types.clone(),
                return_type.clone(),
            ));
        }

        let signature = metadata::Signature {
            flags: metadata::MethodCallAttributes::HASTHIS,
            return_type,
            types,
        };

        let mut is_special = false;
        for attr in &method.attrs {
            if attr.path().is_ident("special") {
                if !matches!(attr.meta, syn::Meta::Path(_)) {
                    return self.err(attr, "`special` attribute does not accept arguments");
                }
                is_special = true;
            }
        }

        let mut flags = base_flags;
        if is_special {
            flags |= metadata::MethodAttributes::SpecialName;
        }

        let method_def = self.output.MethodDef(
            &method.sig.ident.to_string(),
            &signature,
            flags,
            Default::default(),
        );

        self.encode_attrs(
            metadata::writer::HasAttribute::MethodDef(method_def),
            &method.attrs,
            &["special"],
        )?;

        self.encode_return_attrs(&method.return_attrs)?;
        self.encode_params(&params)?;

        Ok(())
    }

    /// Encodes a synthesized `SpecialName` method (property accessor or event accessor).
    ///
    /// `params` is a list of `(name, type)` pairs with no custom attributes; the parameter
    /// direction is inferred from the type. The method always has the `SpecialName` flag.
    fn encode_special_method(
        &mut self,
        name: &str,
        params: &[(&str, &metadata::Type)],
        return_type: metadata::Type,
        base_flags: metadata::MethodAttributes,
        already_has_guid: bool,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
    ) -> Result<(), Error> {
        let types: Vec<metadata::Type> = params.iter().map(|(_, ty)| (*ty).clone()).collect();

        if !already_has_guid {
            method_signatures.push((name.to_string(), types.clone(), return_type.clone()));
        }

        let signature = metadata::Signature {
            flags: metadata::MethodCallAttributes::HASTHIS,
            return_type,
            types,
        };

        let flags = base_flags | metadata::MethodAttributes::SpecialName;

        self.output
            .MethodDef(name, &signature, flags, Default::default());

        self.encode_simple_params(params)?;

        Ok(())
    }
