/// Emits all interface members as token streams.
///
/// Consumes `SpecialName` getter/setter (`get_`/`put_`) pairs into property shorthand
/// (`Name: Type;`), `SpecialName` `add_`/`remove_` pairs into event shorthand
/// (`event Name: HandlerType;` for WinRT interfaces), and falls back to the regular method
/// representation for anything not converted.
fn write_members(
    namespace: &str,
    item: &metadata::reader::TypeDef,
    generics: &[metadata::Type],
) -> Result<Vec<TokenStream>, Error> {
    let methods: Vec<metadata::reader::MethodDef> = item.methods().collect();
    let winrt = item
        .flags()
        .contains(metadata::TypeAttributes::WindowsRuntime);

    let mut consumed = vec![false; methods.len()];
    let mut out = Vec::new();

    for i in 0..methods.len() {
        if consumed[i] {
            continue;
        }

        let method = &methods[i];
        let is_special = method
            .flags()
            .contains(metadata::MethodAttributes::SpecialName);

        if is_special {
            let name = method.name();

            if let Some(prop) = name.strip_prefix("get_") {
                consumed[i] = true;
                let setter = find_unconsumed(&methods, &consumed, i, &format!("put_{prop}"));
                let prop_ident = write_ident(prop);
                let signature = method.signature(generics);
                let ty = write_type(namespace, &signature.return_type);

                if let Some(j) = setter {
                    consumed[j] = true;
                    out.push(quote! { #prop_ident: #ty; });
                } else {
                    out.push(quote! { #[get] #prop_ident: #ty; });
                }
                continue;
            }

            if let Some(prop) = name.strip_prefix("put_") {
                consumed[i] = true;
                let getter = find_unconsumed(&methods, &consumed, i, &format!("get_{prop}"));
                let prop_ident = write_ident(prop);
                let signature = method.signature(generics);
                let ty = signature
                    .types
                    .first()
                    .map(|ty| write_type(namespace, ty))
                    .unwrap_or_default();

                if let Some(j) = getter {
                    consumed[j] = true;
                    out.push(quote! { #prop_ident: #ty; });
                } else {
                    out.push(quote! { #[set] #prop_ident: #ty; });
                }
                continue;
            }

            if winrt {
                if let Some(evt) = name.strip_prefix("add_") {
                    if let Some(j) =
                        find_unconsumed(&methods, &consumed, i, &format!("remove_{evt}"))
                    {
                        consumed[i] = true;
                        consumed[j] = true;
                        let evt_ident = write_ident(evt);
                        let signature = method.signature(generics);
                        let handler_ty = signature
                            .types
                            .first()
                            .map(|ty| write_type(namespace, ty))
                            .unwrap_or_default();
                        out.push(quote! { event #evt_ident: #handler_ty; });
                        continue;
                    }
                }
            }
        }

        consumed[i] = true;
        out.push(write_method(namespace, method, generics)?);
    }

    Ok(out)
}

